const output = [];

const fieldLabels = {
  "Transcript": "TRANSCRIPT",
  "Supporting_Documents": "REFERENCE",
  "Company_Logo_s_": "LOGO"
};

const binaryData = $input.first().binary || {};

for (const [field, label] of Object.entries(fieldLabels)) {
  // Matches the field name exactly (single file) OR field name followed
  // by an index suffix like _0, _1 (n8n's format when multiple files are
  // uploaded to the same field)
  const matchingKeys = Object.keys(binaryData).filter(
    (key) => key === field || key.startsWith(field + "_")
  );

  for (const key of matchingKeys) {
    const file = binaryData[key];
    output.push({
      json: { label, filename: file.fileName || "unknown" },
      binary: { data: file }
    });
  }
}

return output;

'use strict';

// BUILD CONTEXT BLOCK
//
// Extract from File strips the upstream json fields AND does not leave a
// usable filename on the item, so label/filename cannot be recovered from the
// item itself. The previous version fell back to positional matching against
// Flatten Uploads, which is wrong: Merge runs in append mode with Extract PDF
// on input 0, so the merged stream arrives as [PDFs..., TXTs...] while Flatten
// Uploads order is [TRANSCRIPT, REFERENCEs..., LOGOs...]. Index N in one is not
// index N in the other, and every label silently rotated onto the wrong
// document -- putting the consultant pre-work under the TRANSCRIPT label and
// the real transcript under a contact-form label.
//
// The fix is to stop reading the merged stream at all. Each extraction node is
// read directly and zipped against its OWN filtered slice of Flatten Uploads.
// Both sides are in the same order by construction (the IF node preserves
// order, and so does Extract from File), so there is nothing to misalign.
//
// This node stays wired downstream of Merge only so it runs after both
// branches have finished. It does not consume Merge's output.

const LOGO = 'LOGO';

const allSources = $('Flatten Uploads').all()
  .map(function (s) { return s.json || {}; })
  .filter(function (s) { return s.label !== LOGO; });

const isPdf = function (name) { return /\.pdf$/i.test(String(name || '')); };

const pdfSources = allSources.filter(function (s) { return isPdf(s.filename); });
const txtSources = allSources.filter(function (s) { return !isPdf(s.filename); });

function readBranch(nodeName) {
  try {
    return $(nodeName).all();
  } catch (err) {
    // Branch had no items, so the node never executed. Not an error.
    return [];
  }
}

const pdfItems = readBranch('Extract PDF');
const txtItems = readBranch('Extract from TXT');

if (pdfItems.length !== pdfSources.length) {
  throw new Error(
    'Build Context Block: Extract PDF returned ' + pdfItems.length + ' item(s) but Flatten Uploads ' +
    'listed ' + pdfSources.length + ' PDF(s) (' + pdfSources.map(function (s) { return s.filename; }).join(', ') +
    '). Labels cannot be resolved safely -- fix the branch before running.'
  );
}
if (txtItems.length !== txtSources.length) {
  throw new Error(
    'Build Context Block: Extract from TXT returned ' + txtItems.length + ' item(s) but Flatten Uploads ' +
    'listed ' + txtSources.length + ' non-PDF file(s) (' + txtSources.map(function (s) { return s.filename; }).join(', ') +
    '). Labels cannot be resolved safely -- fix the branch before running.'
  );
}

// Pair each extracted item with its source. Where the item still carries a
// filename, assert it agrees rather than trusting the index blindly -- a
// mismatch here is the exact bug this node exists to prevent, so it throws
// instead of quietly continuing.
const docs = [];

function pair(items, sources, branchName) {
  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    const source = sources[i];

    const binName =
      (item.binary && item.binary.data && item.binary.data.fileName) ||
      item.json.fileName ||
      null;

    if (binName && source.filename && binName !== source.filename) {
      throw new Error(
        'Build Context Block: ' + branchName + ' item ' + (i + 1) + ' reports filename "' + binName +
        '" but Flatten Uploads has "' + source.filename + '" at that position. The branch order no ' +
        'longer matches -- do not trust any label in this run.'
      );
    }

    const text = item.json.text || item.json.data || '';

    if (!String(text).trim()) {
      throw new Error(
        'Build Context Block: "' + (source.filename || 'unknown') + '" extracted to empty text. ' +
        'If it is a .docx or another binary format it cannot go down the TXT branch -- convert it to PDF or plain text.'
      );
    }

    if (!source.label) {
      throw new Error('Build Context Block: no label on Flatten Uploads entry for "' + source.filename + '".');
    }

    docs.push({ label: source.label, filename: source.filename, text: text });
  }
}

pair(pdfItems, pdfSources, 'Extract PDF');
pair(txtItems, txtSources, 'Extract from TXT');

if (docs.length === 0) {
  throw new Error('Build Context Block: no documents resolved. Check the uploads reached Flatten Uploads.');
}

// The consultant-side next-phase reference is deliberately separate from the
// discovery record. It travels through the normal extractor for reliable text
// recovery, but never enters context_block or Node A's evidence analysis.
const nextPhaseReferences = docs.filter(function (doc) {
  return doc.label === 'NEXT_PHASE_REFERENCE';
});
if (nextPhaseReferences.length > 1) {
  throw new Error('Build Context Block: only one Next-Phase Reference may be supplied.');
}

const discoveryDocs = docs.filter(function (doc) {
  return doc.label !== 'NEXT_PHASE_REFERENCE';
});
if (discoveryDocs.length === 0) {
  throw new Error('Build Context Block: no discovery documents resolved after separating the optional next-phase reference.');
}

// Transcript first -- it is the primary evidence and everything else is
// supporting material. Node A weights what it reads first.
discoveryDocs.sort(function (a, b) {
  if (a.label === b.label) return 0;
  if (a.label === 'TRANSCRIPT') return -1;
  if (b.label === 'TRANSCRIPT') return 1;
  return 0;
});

if (discoveryDocs[0].label !== 'TRANSCRIPT') {
  console.log('Build Context Block: no TRANSCRIPT-labelled document in this run. Node A will be analysing supporting material only.');
}

let context = '';
for (const doc of discoveryDocs) {
  context += '\n=== [' + doc.label + ': ' + doc.filename + '] ===\n' + doc.text + '\n';
}

console.log('Build Context Block: resolved ' + docs.length + ' document(s), including ' +
  nextPhaseReferences.length + ' separately held future-state reference(s) -> ' +
  docs.map(function (d) { return d.label + ':' + d.filename; }).join(', '));

return [{
  json: {
    context_block: context,
    next_phase_reference: nextPhaseReferences.length ? nextPhaseReferences[0].text : null
  }
}];

// Convert each uploaded logo through n8n's binary-data helper. This works
// with filesystem-backed binary storage and keeps the file metadata intact.
const items = $input.all();
const output = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  if (!item.binary || !item.binary.data) {
    throw new Error('Logo to Base64: logo item ' + (i + 1) + ' has no binary.data payload.');
  }

  let buffer;
  try {
    buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
  } catch (err) {
    throw new Error('Logo to Base64: could not read logo item ' + (i + 1) + ' (' + (item.json.filename || 'unnamed file') + '): ' + err.message);
  }

  if (!buffer || !buffer.length) {
    throw new Error('Logo to Base64: logo item ' + (i + 1) + ' (' + (item.json.filename || 'unnamed file') + ') is empty or unreadable.');
  }

  output.push({
    json: { ...item.json, data: buffer.toString('base64') },
    binary: { data: item.binary.data }
  });
}

return output;

'use strict';

// BUILD LOGO DATA URI
// Emits every uploaded logo as a data URI, in upload order. The audit covers
// two businesses and carries both logos, so this must not collapse to the
// first file the way it did when the engagement was single-entity.

const items = $input.all();

if (items.length < 1 || items.length > 2) {
  throw new Error('Build Logo Data URI: this audit requires one or two logos; received ' + items.length + '.');
}

if (items.length === 0) {
  return [{ json: { logo_data_uris: [] } }];
}

const uris = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const mimeType = (item.binary && item.binary.data && item.binary.data.mimeType) || 'image/png';
  const base64 = item.json.data || item.json.base64 || '';

  if (!base64) {
    throw new Error('Build Logo Data URI: logo ' + (i + 1) + ' of ' + items.length + ' has no base64 payload. Check Logo to Base64 ran on every LOGO item.');
  }

  uris.push('data:' + mimeType + ';base64,' + base64);
}

return [{ json: { logo_data_uris: uris } }];

'use strict';

// HARDEN STATS PARSED
// Parses Node A's JSON and recomputes every hours figure from the underlying
// facts (hours before, hours after, occurrences). Node A stays responsible for
// reading the transcript and judging what the future state looks like -- that's
// language understanding, code can't do it. This node just makes sure the
// arithmetic built on top of those judgments is always exactly right.
//
// HOURS ARE THE HEADLINE; COST IS ALLOWED ONLY AS NARRATIVE COLOUR.
// No rate, no money formatter -- nothing in this node computes a dollar
// figure. A cost figure IS allowed through, but only if Node A reported one
// that was actually stated in the session, and only inside a short, fixed
// set of narrative fields (see section 3c). It must never appear in totals,
// headline_kpis, a workflow's core hours fields, a supporting_flow, or
// evaluated_need_more_research. Section 3c enforces this allowlist and
// throws with the offending field path(s) if it's violated.
//
// THREE WORKFLOWS ONLY. The audit proposes exactly three workflows and they are
// the only things that carry figures. Everything else is a supporting_flow:
// named, described, and deliberately unquantified.

const HOURS_PER_WORKING_DAY = 7.6;
const REQUIRED_WORKFLOWS = 3;

// 1. Find the text in the model response. Extended-thinking models
// return a thinking block first, so content[0] is not reliably the answer.
const raw = $input.first().json;
const blocks = Array.isArray(raw && raw.content) ? raw.content : [];
const textBlock = blocks.find(function (b) {
  return b && b.type === 'text' && typeof b.text === 'string';
});
// DeepSeek (OpenAI-compatible) returns choices[0].message.content instead.
const choice = raw && Array.isArray(raw.choices) ? raw.choices[0] : null;
if (choice && choice.finish_reason === 'length') {
  throw new Error('The model hit max_tokens and the response was cut off. Raise max_tokens in the System Prompt node, or switch to a model with a larger output limit.');
}
const choiceText = choice && choice.message && typeof choice.message.content === 'string'
  ? choice.message.content.replace(/^\s*```[a-z]*\s*/i, '').replace(/\s*```\s*$/, '')
  : null;
const rawText = choiceText || (textBlock ? textBlock.text : null);

if (!rawText) {
  throw new Error('Harden Stats Parsed: no text block found on the response. Block types present: ' + blocks.map(function (b) { return b && b.type; }).join(', ') + '. Check the Anthropic node output shape has not changed.');
}

// 2. Parse it, with a targeted repair for stray quotes and raw newlines inside
// string values. The repair only escapes characters that are already illegal
// where they sit; it never reorders or drops content.
function salvageJson(text) {
  const first = text.indexOf('{');
  const last = text.lastIndexOf('}');
  if (first === -1 || last === -1 || last <= first) return null;

  const s = text.slice(first, last + 1);
  let out = '';
  let inString = false;
  let escaped = false;

  for (let i = 0; i < s.length; i++) {
    const c = s[i];

    if (escaped) { out += c; escaped = false; continue; }
    if (c === '\\') { out += c; escaped = true; continue; }

    if (c === '"') {
      if (!inString) { inString = true; out += c; continue; }
      let j = i + 1;
      while (j < s.length && /\s/.test(s[j])) j++;
      if (j >= s.length || s[j] === ',' || s[j] === '}' || s[j] === ']' || s[j] === ':') {
        inString = false;
        out += c;
      } else {
        out += '\\"';
      }
      continue;
    }

    if (inString && (c === '\n' || c === '\r')) { out += '\\n'; continue; }
    if (inString && c === '\t') { out += '\\t'; continue; }

    out += c;
  }

  return out;
}

let data;
let salvaged = false;
try {
  data = JSON.parse(rawText);
} catch (firstErr) {
  const repaired = salvageJson(rawText);
  if (repaired) {
    try {
      data = JSON.parse(repaired);
      salvaged = true;
      console.log('Harden Stats Parsed: first parse failed (' + firstErr.message + ') but salvage succeeded. Node A is emitting illegal characters inside string values -- check the JSON hygiene rules are still in its system prompt.');
    } catch (secondErr) {
      // fall through to the throw below
    }
  }

  if (!data) {
    const trimmedEnd = rawText.trim().slice(-1);
    const looksTruncated = trimmedEnd !== '}';
    const posMatch = /position (\d+)/.exec(firstErr.message);
    let window = '';
    if (posMatch) {
      const pos = Number(posMatch[1]);
      window = ' ... Around the failure: ...' +
        rawText.slice(Math.max(0, pos - 150), pos) +
        ' <<<HERE>>> ' +
        rawText.slice(pos, pos + 150) + '...';
    }
    throw new Error(
      'Harden Stats Parsed: JSON.parse failed and could not be salvaged -- ' + firstErr.message +
      (looksTruncated
        ? ' The response does not end with a closing brace, so it was most likely TRUNCATED -- raise max_tokens on the Anthropic node. Note that thinking tokens count against the same budget.'
        : '') +
      window
    );
  }
}

// 3. Structural sanity checks
if (!Array.isArray(data.workflows) || data.workflows.length < 1) {
  throw new Error('Harden Stats Parsed: workflows array is missing or empty.');
}

// 3a. Exactly three workflows. The three are the audit's whole argument and
// the only entries that carry figures; anything else Node A wants to include
// belongs in supporting_flows.
if (data.workflows.length !== REQUIRED_WORKFLOWS) {
  throw new Error(
    'Harden Stats Parsed: Node A returned ' + data.workflows.length + ' workflows. This audit proposes exactly ' +
    REQUIRED_WORKFLOWS + '. Anything beyond the three belongs in supporting_flows, described but unquantified. ' +
    'Workflows returned: ' + data.workflows.map(function (w) { return w.id + ' (' + w.name + ')'; }).join('; ') +
    '. Do not raise this number -- restricting the arithmetic to three well-evidenced workflows is what stops a ' +
    'weakly-sourced one from dominating the headline figure.'
  );
}

// 3b. Occurrence counts alone cannot establish semantic overlap. A numerical
// subset-sum can occur across independent cadences -- channel shares derived
// from a common weekly total legitimately coincide with other schedules.
// Semantic overlap is governed by Node A's step/trigger review. This node
// validates structure and arithmetic only.

// 3c. MONEY ALLOWLIST SWEEP.
// A cost figure is permitted only where Node A's prompt allows it: a
// workflow's stuck_point, a pain point's root_cause or business_impact,
// executive_summary narrative text, or a key_indicator whose own measures is
// "cost". Everywhere else -- totals, headline_kpis, every workflow's core
// hours fields, every supporting_flow field, evaluated_need_more_research,
// and any key_indicator NOT marked measures:"cost" -- currency is still
// banned outright. The pattern requires a symbol or code adjacent to a
// number, so ordinary prose about value or cost is not caught, only actual
// figures. meta is exempt: business names and locations are form-supplied,
// not model output.
const MONEY_PATTERN = /(?:[$£€]\s?\d|\d\s?(?:AUD|USD|GBP|EUR|SEK)\b|\bAUD\s?\d|\bUSD\s?\d|\bper\s+hour\b\s*[:=]?\s*\d)/i;
const MONEY_ALLOWED_PATH = /^(workflows\[\d+\]\.stuck_point|pain_points\[\d+\]\.(root_cause|business_impact)|executive_summary\.(overview|strengths|primary_constraint|opening_note|growth_opportunity|top_findings\[\d+\]\.text)|presentation_brief\.(emphasis_notes\[\d+\]|narrative_arc|lead_with))$/;

const moneyHits = [];

(function sweep(node, path) {
  if (node === null || node === undefined) return;
  if (typeof node === 'string') {
    if (MONEY_PATTERN.test(node) && !MONEY_ALLOWED_PATH.test(path)) {
      moneyHits.push(path + ' -> ' + node.slice(0, 160));
    }
    return;
  }
  if (Array.isArray(node)) {
    for (let i = 0; i < node.length; i++) sweep(node[i], path + '[' + i + ']');
    return;
  }
  if (typeof node === 'object') {
    for (const k of Object.keys(node)) {
      if (path === '' && k === 'meta') continue;
      // key_indicators gets bespoke handling below -- its allow/deny depends
      // on a sibling field (measures), which a pure path-based sweep can't see.
      if (path === '' && k === 'key_indicators') continue;
      sweep(node[k], path === '' ? k : path + '.' + k);
    }
  }
})(data, '');

// key_indicators: currency is allowed only inside an entry whose own
// measures is "cost". A handling_time, volume, rate, or ratio indicator
// carrying a dollar sign is always wrong, regardless of what the workflow
// it references is allowed to say.
if (Array.isArray(data.key_indicators)) {
  data.key_indicators.forEach(function (ki, i) {
    const isCost = ki && ki.measures === 'cost';
    ['label', 'scenario', 'value_fmt', 'source_quote'].forEach(function (f) {
      const val = ki && ki[f];
      if (typeof val === 'string' && MONEY_PATTERN.test(val) && !isCost) {
        moneyHits.push('key_indicators[' + i + '].' + f + ' -> ' + val.slice(0, 160));
      }
    });
  });
}

if (moneyHits.length) {
  throw new Error(
    'Harden Stats Parsed: currency found outside the fields where this audit allows it. A cost figure is only ' +
    'permitted when the session actually stated one, and only inside a workflow\'s stuck_point, a pain point\'s ' +
    'root_cause or business_impact, executive_summary narrative text, or a key_indicator whose own measures is ' +
    '"cost". It must never appear in totals, headline_kpis, a workflow\'s core hours fields, a supporting_flow, ' +
    'or evaluated_need_more_research. Offending fields: ' + moneyHits.join(' | ')
  );
}

// Drop anything left over from retired schema revisions rather than forwarding
// it. This node's output is stringified wholesale into Node B's user message.
if (data.meta) {
  delete data.meta.rate;
  delete data.meta.currency;
  delete data.meta.currency_symbol;
}
for (const wf of data.workflows) {
  delete wf.levels;
  delete wf.parent_id;
}
delete data.automation_options;
delete data.remaining_opportunities;
if (data.executive_summary) delete data.executive_summary.top_findings;

// 3d. Overwrite form-supplied values in meta from Final Build, the only
// trustworthy source. The labour rate and currency are deliberately NOT read
// across: still captured on the form, still recorded on Final Build, consumed
// by nothing -- unrelated to the cost-as-colour allowance above, which is
// about figures Node A pulls from the transcript, never the form's rate field.
//
// Logo COUNT is recorded here; the logo BYTES deliberately are not, because
// this object becomes a model prompt. The bytes stay on Final Build and
// Extract HTML reaches back there after generation.
let finalBuildJson;
try {
  finalBuildJson = $('Final Build').first().json;
} catch (err) {
  throw new Error('Harden Stats Parsed: could not reach Final Build to re-inject the form-supplied values -- ' + err.message);
}

const fbMeta = finalBuildJson.meta || {};

data.meta = data.meta || {};
data.meta.business_name = fbMeta.business_name || null;
data.meta.prepared_for = fbMeta.prepared_for || null;
data.meta.location = fbMeta.location || null;

const logoUris = Array.isArray(finalBuildJson.logo_data_uris) ? finalBuildJson.logo_data_uris : [];
data.meta.logo_count = logoUris.length;

const hrs = function (n) { return (Math.round(n * 10) / 10).toString().replace(/\.0$/, ''); };
const hrsFmt = function (n) { return hrs(n) + ' hrs'; };
const daysFmt = function (n) { return hrs(n) + ' days'; };

// 4. Recompute each workflow's figures from the raw facts.
for (const wf of data.workflows) {
  const before = Number(wf.before && wf.before.hours_per_occurrence);
  const occ = Number(wf.occurrences_per_year);

  if (!Number.isFinite(before) || before < 0) {
    throw new Error('Harden Stats Parsed: workflow "' + wf.id + '" has an invalid before.hours_per_occurrence.');
  }
  if (!Number.isFinite(occ) || occ < 1 || occ > 10000) {
    throw new Error('Harden Stats Parsed: workflow "' + wf.id + '" has occurrences_per_year outside 1-10,000.');
  }

  const after = Number(wf.after && wf.after.hours_per_occurrence);
  if (!Number.isFinite(after) || after < 0) {
    throw new Error('Harden Stats Parsed: workflow "' + wf.id + '" has an invalid after.hours_per_occurrence.');
  }
  if (after > before) {
    throw new Error('Harden Stats Parsed: workflow "' + wf.id + '" after.hours_per_occurrence (' + after + ') exceeds before.hours_per_occurrence (' + before + ').');
  }

  const savedHoursPerYear = Math.max(0, before - after) * occ;
  const savedHoursPerWeek = savedHoursPerYear / 52;
  const currentHoursPerYear = before * occ;
  const futureHoursPerYear = after * occ;
  const currentHoursPerWeek = currentHoursPerYear / 52;
  const futureHoursPerWeek = futureHoursPerYear / 52;

  wf.saved_hours_per_year = Math.round(savedHoursPerYear * 10) / 10;
  wf.saved_hours_per_year_fmt = hrsFmt(wf.saved_hours_per_year);
  wf.saved_hours_per_week = Math.round(savedHoursPerWeek * 10) / 10;
  wf.saved_hours_per_week_fmt = hrsFmt(wf.saved_hours_per_week);

  wf.current_hours_per_year = Math.round(currentHoursPerYear * 10) / 10;
  wf.current_hours_per_year_fmt = hrsFmt(wf.current_hours_per_year);
  wf.current_hours_per_week = Math.round(currentHoursPerWeek * 10) / 10;
  wf.current_hours_per_week_fmt = hrsFmt(wf.current_hours_per_week);
  wf.future_hours_per_year = Math.round(futureHoursPerYear * 10) / 10;
  wf.future_hours_per_year_fmt = hrsFmt(wf.future_hours_per_year);
  wf.future_hours_per_week = Math.round(futureHoursPerWeek * 10) / 10;
  wf.future_hours_per_week_fmt = hrsFmt(wf.future_hours_per_week);

  wf.reduction_percent = currentHoursPerYear > 0
    ? Math.round((savedHoursPerYear / currentHoursPerYear) * 100)
    : 0;
  wf.reduction_percent_fmt = wf.reduction_percent + '%';

  if (savedHoursPerYear === 0) {
    console.log('Harden Stats Parsed: workflow "' + wf.id + '" (' + wf.name + ') saves zero hours -- after equals before. Confirm this is deliberate.');
  }

  if (wf.build_days !== undefined && wf.build_days !== null) {
    const bd = Number(wf.build_days);
    if (!Number.isFinite(bd) || bd <= 0 || bd > 60) {
      console.log('Harden Stats Parsed: workflow "' + wf.id + '" has build_days=' + wf.build_days + ', outside the plausible 0-60 range. Left as-is; check it is days of effort and not hours.');
    }
  }

  const FSC = ['high', 'medium', 'low'];
  if (!FSC.includes(String(wf.future_state_confidence || '').toLowerCase())) {
    wf.future_state_confidence = 'medium';
    console.log('Harden Stats Parsed: workflow "' + wf.id + '" had no usable future_state_confidence. Defaulted to medium -- the client asked specifically how confident we are in the proposed steps.');
  }
  if (wf.future_state_confidence !== 'high' && !wf.future_state_note) {
    console.log('Harden Stats Parsed: workflow "' + wf.id + '" is ' + wf.future_state_confidence + ' confidence but has no future_state_note saying what needs confirming.');
  }
  if (!wf.stays_human) {
    console.log('Harden Stats Parsed: workflow "' + wf.id + '" has no stays_human value.');
  }
}

const wfById = {};
for (const wf of data.workflows) { wfById[wf.id] = wf; }

// 3e. Supporting flows: attached, named, and strictly unquantified -- no
// numbers of any kind, cost figures included.
const NUMERIC_FIELDS_BANNED = [
  'occurrences_per_year', 'saved_hours_per_year', 'saved_hours_per_week',
  'current_hours_per_year', 'current_hours_per_week',
  'future_hours_per_year', 'future_hours_per_week', 'reduction_percent',
  'impact_score', 'complexity_score', 'build_days', 'before', 'after',
  'saved_hours_per_year_fmt', 'saved_hours_per_week_fmt',
  'current_hours_per_year_fmt', 'current_hours_per_week_fmt',
  'future_hours_per_year_fmt', 'future_hours_per_week_fmt', 'reduction_percent_fmt'
];

if (!Array.isArray(data.supporting_flows)) data.supporting_flows = [];

const validSupportingFlows = [];
for (const sf of data.supporting_flows) {
  const flowName = sf.name || sf.id || 'unnamed supporting flow';
  if (!sf.parent_id || !wfById[sf.parent_id]) {
    console.log(
      'Harden Stats Parsed: omitted orphaned supporting flow "' + flowName + '" with parent_id "' +
      (sf.parent_id || 'missing') + '". Supporting flows must attach to one of the three returned workflows (' +
      Object.keys(wfById).join(', ') + '). The core three-workflow audit will continue.'
    );
    continue;
  }

  const stripped = [];
  for (const f of NUMERIC_FIELDS_BANNED) {
    if (sf[f] !== undefined) { delete sf[f]; stripped.push(f); }
  }
  if (stripped.length) {
    console.log('Harden Stats Parsed: stripped quantified fields from supporting flow "' + flowName + '": ' + stripped.join(', ') + '. Supporting flows are described, never measured.');
  }
  validSupportingFlows.push(sf);
}
data.supporting_flows = validSupportingFlows;

// 4b. Cross-check key indicators against the workflows they claim to describe.
// A workflow may legitimately have several handling_time variants, so the
// baseline must sit within the range those indicators span rather than
// matching one exactly. measures !== 'handling_time' (including 'cost') is
// skipped here -- a cost indicator has nothing to cross-check against hours.
const UNIT_TO_HOURS = {
  minute: 1 / 60, minutes: 1 / 60, min: 1 / 60, mins: 1 / 60,
  hour: 1, hours: 1, hr: 1, hrs: 1
};
const SINGLE_INDICATOR_TOLERANCE = 0.05;
const RANGE_EDGE_TOLERANCE = 0.02;

const handlingByWorkflow = {};

for (const ki of (data.key_indicators || [])) {
  if (!ki.workflow_ref) continue;

  const wf = wfById[ki.workflow_ref];
  if (!wf) {
    console.log('Harden Stats Parsed: key_indicator "' + ki.label + '" references "' + ki.workflow_ref + '", which is not one of the three workflows. Unlinked -- it will render as an unattached figure.');
    ki.workflow_ref = null;
    continue;
  }

  if (ki.measures && ki.measures !== 'handling_time') continue;

  const mult = UNIT_TO_HOURS[String(ki.unit || '').toLowerCase()];
  if (!mult) continue;

  const kiHours = Number(ki.value) * mult;
  if (!Number.isFinite(kiHours)) continue;

  if (!handlingByWorkflow[ki.workflow_ref]) handlingByWorkflow[ki.workflow_ref] = [];
  handlingByWorkflow[ki.workflow_ref].push({ label: ki.label, hours: kiHours, scenario: ki.scenario });
}

for (const wfId of Object.keys(handlingByWorkflow)) {
  const wf = wfById[wfId];
  const wfHours = Number(wf.before && wf.before.hours_per_occurrence);
  if (!Number.isFinite(wfHours) || wfHours <= 0) continue;

  const candidates = handlingByWorkflow[wfId];
  const listed = candidates.map(function (c) {
    return '"' + c.label + '" = ' + c.hours.toFixed(3) + ' hrs';
  }).join('; ');

  if (candidates.length === 1) {
    const only = candidates[0].hours;
    if (Math.abs(only - wfHours) / wfHours > SINGLE_INDICATOR_TOLERANCE) {
      throw new Error(
        'Harden Stats Parsed: workflow "' + wfId + '" (' + wf.name + ') has before.hours_per_occurrence=' +
        wfHours + ', which does not match its only handling_time indicator: ' + listed +
        '. Where a workflow has one measured handling time, the baseline must equal it.'
      );
    }
    continue;
  }

  const values = candidates.map(function (c) { return c.hours; });
  const min = Math.min.apply(null, values);
  const max = Math.max.apply(null, values);

  if (wfHours < min * (1 - RANGE_EDGE_TOLERANCE) || wfHours > max * (1 + RANGE_EDGE_TOLERANCE)) {
    throw new Error(
      'Harden Stats Parsed: workflow "' + wfId + '" (' + wf.name + ') has before.hours_per_occurrence=' +
      wfHours + ', outside the range spanned by its handling_time indicators (' + min.toFixed(3) + ' to ' +
      max.toFixed(3) + ' hrs): ' + listed + '. The baseline must sit within the measured range.'
    );
  }

  const matchesAnEdge = values.some(function (v) {
    return Math.abs(v - wfHours) / wfHours <= SINGLE_INDICATOR_TOLERANCE;
  });
  if (!matchesAnEdge) {
    const note = String(wf.future_state_note || '') + ' ' + String(wf.before && wf.before.description || '');
    const declared = /average|weighted|blend|combin|mix|between|range|both/i.test(note);
    if (!declared) {
      throw new Error(
        'Harden Stats Parsed: workflow "' + wfId + '" (' + wf.name + ') has before.hours_per_occurrence=' +
        wfHours + ', which is a blend of its handling_time indicators (' + listed + ') but is not declared as one. ' +
        'Blending is allowed, but before.description or future_state_note must say which sub-cases the figure spans.'
      );
    }
    console.log('Harden Stats Parsed: workflow "' + wfId + '" uses a declared blended baseline (' + wfHours + ' hrs) across ' + candidates.length + ' measured scenarios.');
  }
}

// 4c. Provenance warnings. Not fatal.
for (const ki of (data.key_indicators || [])) {
  if (!ki.scenario || !ki.source_quote) {
    console.log('Harden Stats Parsed: key_indicator "' + ki.label + '" is missing scenario or source_quote.');
  }
  if (!ki.measures) {
    console.log('Harden Stats Parsed: key_indicator "' + ki.label + '" is missing measures -- it will be treated as handling_time by the cross-check.');
  }
}

// 4d. Pain point -> workflow mapping.
const painTitles = {};
for (const pp of (data.pain_points || [])) {
  painTitles[pp.title] = true;

  if (!Array.isArray(pp.workflow_refs)) pp.workflow_refs = [];

  const kept = pp.workflow_refs.filter(function (ref) { return !!wfById[ref]; });
  if (kept.length !== pp.workflow_refs.length) {
    console.log('Harden Stats Parsed: pain point "' + pp.title + '" referenced workflows outside the three. Unresolvable refs dropped.');
    pp.workflow_refs = kept;
  }

  if (!pp.workflow_refs.length) {
    console.log('Harden Stats Parsed: pain point "' + pp.title + '" maps to no workflow -- it will render as not addressed by this audit.');
  }
}

for (const ki of (data.key_indicators || [])) {
  if (ki.pain_point_ref && !painTitles[ki.pain_point_ref]) {
    console.log('Harden Stats Parsed: key_indicator "' + ki.label + '" has pain_point_ref "' + ki.pain_point_ref + '", which matches no pain point title. Cleared.');
    ki.pain_point_ref = null;
  }
}

// 4e. Downgrade workflows whose baseline has no measured figure behind it.
data.integrity_flags = [];

for (const wf of data.workflows) {
  if (handlingByWorkflow[wf.id]) continue;

  const baseline = wf.before && wf.before.hours_per_occurrence;

  if (wf.confidence === 'verified') {
    wf.confidence = 'estimate';
    data.integrity_flags.push({
      workflow_id: wf.id,
      workflow_name: wf.name,
      field: 'before.hours_per_occurrence',
      value: baseline,
      reason: 'No handling_time key_indicator references this workflow, so the baseline was derived rather than stated in the session. Downgraded from verified to estimate.'
    });
    console.log('Harden Stats Parsed: DOWNGRADED workflow "' + wf.id + '" (' + wf.name + ') from verified to estimate.');
  } else {
    console.log('Harden Stats Parsed: workflow "' + wf.id + '" (' + wf.name + ') has a derived baseline (' + baseline + ') and is already marked ' + wf.confidence + '.');
  }
}

data.totals_confidence = data.integrity_flags.length ? 'estimate' : 'verified';

// 5. Audit-wide totals. The sum of the THREE workflows only -- supporting
// flows contribute nothing by design.
const savedHours = data.workflows.reduce(function (sum, wf) { return sum + wf.saved_hours_per_year; }, 0);
const currentHours = data.workflows.reduce(function (sum, wf) { return sum + wf.current_hours_per_year; }, 0);
const futureHours = data.workflows.reduce(function (sum, wf) { return sum + wf.future_hours_per_year; }, 0);

const hoursPerYear = Math.round(savedHours);
const hoursPerWeek = Math.round((savedHours / 52) * 10) / 10;
const workingDays = Math.round((savedHours / HOURS_PER_WORKING_DAY) * 10) / 10;
const reductionPercent = currentHours > 0 ? Math.round((savedHours / currentHours) * 100) : 0;

const approx = data.totals_confidence === 'estimate' ? '~' : '';

const volumeBasis = (data.totals && data.totals.volume_basis) || null;
if (!volumeBasis) {
  console.log('Harden Stats Parsed: totals.volume_basis is empty. The client asked specifically for the figures to state what volumes they rest on.');
}

data.totals = {
  current_hours_per_year: Math.round(currentHours),
  current_hours_per_year_fmt: approx + hrsFmt(Math.round(currentHours)),
  current_hours_per_week: Math.round((currentHours / 52) * 10) / 10,
  current_hours_per_week_fmt: approx + hrsFmt(Math.round((currentHours / 52) * 10) / 10),
  future_hours_per_year: Math.round(futureHours),
  future_hours_per_year_fmt: approx + hrsFmt(Math.round(futureHours)),
  hours_freed_per_year: hoursPerYear,
  hours_freed_per_year_fmt: approx + hrsFmt(hoursPerYear),
  hours_freed_per_week: hoursPerWeek,
  hours_freed_per_week_fmt: approx + hrsFmt(hoursPerWeek),
  working_days_freed_per_year: workingDays,
  working_days_freed_per_year_fmt: approx + daysFmt(workingDays),
  reduction_percent: reductionPercent,
  reduction_percent_fmt: reductionPercent + '%',
  hours_per_working_day: HOURS_PER_WORKING_DAY,
  workflow_count: data.workflows.length,
  supporting_flow_count: data.supporting_flows.length,
  volume_basis: volumeBasis
};

// 6. Resolve presentation_brief.headline_kpis from structured references into
// final display strings, using the hardened totals above.
const METRIC_LABELS = {
  hours_freed_per_year: 'Hours freed per year',
  hours_freed_per_week: 'Hours freed per week',
  working_days_freed_per_year: 'Working days freed per year',
  current_hours_per_year: 'Hours spent on these tasks per year today',
  current_hours_per_week: 'Hours spent on these tasks per week today',
  reduction_percent: 'Reduction in time spent'
};

function resolveHeadlineKpis(brief, totals, keyIndicators) {
  if (!brief || !Array.isArray(brief.headline_kpis)) return [];

  return brief.headline_kpis.map(function (item) {
    if (typeof item === 'string') {
      return 'Unresolved headline KPI reference: ' + item + ' -- headline_kpis entries must be objects with a metric field, not free text.';
    }

    if (item.metric === 'key_indicator') {
      const match = (keyIndicators || []).find(function (ki) {
        return ki.label === item.key_indicator_label;
      });
      if (!match) {
        return item.key_indicator_label + ' (figure unavailable -- label did not match key_indicators)';
      }
      if (match.measures === 'cost') {
        console.log('Harden Stats Parsed: presentation_brief.headline_kpis referenced a cost-measured key_indicator ("' + match.label + '"). Cost is never a headline figure -- dropped from the resolved list.');
        return null;
      }
      return match.label + ' (' + match.value_fmt + ')';
    }

    const label = METRIC_LABELS[item.metric];
    if (!label) {
      return 'Unresolved headline KPI reference: ' + JSON.stringify(item) + ' -- money and automation-level metrics no longer exist.';
    }

    return label + ' (' + totals[item.metric + '_fmt'] + ')';
  }).filter(function (x) { return x !== null; });
}

if (data.presentation_brief) {
  data.presentation_brief.headline_kpis = resolveHeadlineKpis(data.presentation_brief, data.totals, data.key_indicators);
}

data._salvaged_json = salvaged;

return [{ json: data }];

'use strict';

// EXTRACT HTML
// Pulls the raw HTML document out of Node B's response and substitutes the
// real logo data into the placeholders Node B wrote. Guards against a
// truncated or malformed response, and against a placeholder/logo count
// mismatch in either direction.

const PLACEHOLDERS = ['__LOGO_DATA_URI__', '__LOGO_DATA_URI_2__'];

const raw = $input.first().json;
const blocks = Array.isArray(raw && raw.content) ? raw.content : [];
const textBlock = blocks.find(function (b) {
  return b && b.type === 'text' && typeof b.text === 'string';
});
// DeepSeek (OpenAI-compatible) returns choices[0].message.content instead.
const choice = raw && Array.isArray(raw.choices) ? raw.choices[0] : null;
if (choice && choice.finish_reason === 'length') {
  throw new Error('The model hit max_tokens and the response was cut off. Raise max_tokens in the System Prompt node, or switch to a model with a larger output limit.');
}
const choiceText = choice && choice.message && typeof choice.message.content === 'string'
  ? choice.message.content.replace(/^\s*```[a-z]*\s*/i, '').replace(/\s*```\s*$/, '')
  : null;
const html = choiceText || (textBlock ? textBlock.text : null);

if (!html) {
  throw new Error('Extract HTML: no text block found on the response. Block types present: ' + blocks.map(function (b) { return b && b.type; }).join(', ') + '. Check the Anthropic API response shape has not changed.');
}

const trimmed = html.trim();

const startsOk = /^<!DOCTYPE html>/i.test(trimmed);
const endsOk = /<\/html>\s*$/i.test(trimmed);

if (!startsOk || !endsOk) {
  throw new Error(
    'Extract HTML: response does not look like a complete HTML document. ' +
    'starts_with_doctype=' + startsOk + ', ends_with_html_tag=' + endsOk + '. ' +
    (startsOk && !endsOk
      ? 'It starts correctly but does not close, so it was most likely TRUNCATED -- raise max_tokens in the HTTP Request body. Note that thinking tokens count against the same budget. '
      : '') +
    'First 200 chars: ' + trimmed.slice(0, 200) + ' ... ' +
    'Last 200 chars: ' + trimmed.slice(-200)
  );
}

let fileName = 'audit-dashboard.html';
try {
  const businessName = $('Harden Stats Parsed').first().json.meta.business_name;
  if (businessName) {
    const slug = String(businessName)
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/(^-|-$)/g, '');
    if (slug) {
      fileName = slug + '-audit-dashboard.html';
    }
  }
} catch (err) {
  // Harden Stats Parsed not found or shape changed -- use the default name.
}

// The logo BYTES deliberately do NOT travel through Harden Stats Parsed:
// Harden's output is stringified wholesale into Node B's user message, so
// putting base64 there would undo the placeholder design. Harden carries
// meta.logo_count only; the real bytes are read here, from Final Build,
// after generation is finished.
let logoUris = [];
try {
  const fb = $('Final Build').first().json;
  logoUris = Array.isArray(fb.logo_data_uris) ? fb.logo_data_uris : [];
} catch (err) {
  throw new Error('Extract HTML: could not reach Final Build to resolve the logos -- ' + err.message);
}

if (logoUris.length > PLACEHOLDERS.length) {
  throw new Error('Extract HTML: ' + logoUris.length + ' logos were uploaded but only ' + PLACEHOLDERS.length + ' placeholders are defined. Add another placeholder to this node and to the Node B prompt, or upload fewer logos.');
}

// Check each placeholder against whether a logo exists for it, in both
// directions. A placeholder with no logo ships as a dead literal string in
// an img src; a logo with no placeholder ships a dashboard missing a brand.
for (let i = 0; i < PLACEHOLDERS.length; i++) {
  const present = trimmed.indexOf(PLACEHOLDERS[i]) !== -1;
  const hasUri = !!logoUris[i];

  if (hasUri && !present) {
    throw new Error('Extract HTML: logo ' + (i + 1) + ' was uploaded but Node B did not emit ' + PLACEHOLDERS[i] + ' anywhere in its output. Check meta.logo_count reached the model as ' + logoUris.length + '.');
  }
  if (!hasUri && present) {
    throw new Error('Extract HTML: Node B emitted ' + PLACEHOLDERS[i] + ' but only ' + logoUris.length + ' logo(s) were uploaded. That img src would be left as a dead literal string.');
  }
}

// Substitute in reverse order so a shorter placeholder can never eat part of
// a longer one, and split/join rather than .replace() so every occurrence is
// hit and $&-style patterns in the replacement value are not interpreted.
let finalHtml = trimmed;
for (let i = PLACEHOLDERS.length - 1; i >= 0; i--) {
  if (logoUris[i]) {
    finalHtml = finalHtml.split(PLACEHOLDERS[i]).join(logoUris[i]);
  }
}

return [{
  json: {
    final_html: finalHtml,
    file_name: fileName
  }
}];

assignments.value:
You are the analyst for a client-facing automation audit. Read the discovery material, extract the work that was actually discussed, and return one complete JSON data package for a presenter. The presenter will render your package directly; it will not redo analysis or arithmetic.

Return **only one valid JSON object**. Do not use Markdown, code fences, commentary, or prose outside the object. Keep transcript-derived language concise and paraphrased. Do not invent names, systems, figures, tools, or certainty.

## Audit model

This is an **hours-first** audit. Show where manual time is spent, which three proposed workflows could reduce it, and what remains human. Hours are the headline throughout. Never calculate a dollar saving, ROI, payback, or cost from time, labour rate, or any other input. You may repeat a cost, fee, subsidy, or dollar figure only when it was explicitly stated in the source material, and only as quiet narrative context in `executive_summary` text, `workflows[].stuck_point`, `pain_points[].root_cause` or `business_impact`, or a `key_indicators[]` entry where `measures` is `cost`. Never put money in totals, headline KPIs, core workflow figures, supporting flows, or `evaluated_need_more_research`.

Build exactly **three** quantified workflows. They are the complete quantified case. Select the three best-evidenced, clearly scoped workflow areas that address the client’s own pain points. Each workflow must be distinct: do not count the same business event, customer interaction, record creation, follow-up, or back-office activity twice.

Everything adjacent, smaller, later-stage, or shared should be a `supporting_flow` linked to one of the three parent workflow IDs. Supporting flows are useful context, not separate proposals: they contain no hours, occurrences, scores, build days, costs, percentages, or other numerical claims. Every supporting flow needs a valid `parent_id` and concise source-grounded descriptive content.

## Transcript-led workflow selection
Workflow selection is evidence extraction, not invention. Select exactly three primary workflow areas directly from the discovery transcript: every selected item must have a distinct business trigger, describe the manual work actually discussed, and address a material client pain point. You may use concise, client-facing workflow names and select the three strongest candidates; you do not need to include every activity mentioned in the session. Never elevate an isolated tool action, a routine message, record creation, a discount-code step, or another narrow sub-step into a parent workflow unless the transcript discussed it as a distinct end-to-end business journey.

Use supporting flows for smaller, adjacent, shared, later-stage, or explanatory activities that belong within a selected main journey. Supporting flows must clarify a stage of the parent journey, enable it, or address a smaller problem within it. Do not use a supporting flow to add an unrelated fourth proposal, and do not give it figures.


## Evidence and calculations

Use a value as `verified` only when the source states it directly. Use `estimate` when it is inferred, approximate, or built from a stated range. Keep a scenario-specific handling time with the workflow and indicator it describes; never borrow it for another channel or scenario. A workflow’s `before.hours_per_occurrence` must agree with its own `handling_time` indicator. When a genuine blended baseline is needed, state which sub-cases it spans in `before.description`.

For each workflow, provide only the raw calculation inputs: `before.hours_per_occurrence`, `after.hours_per_occurrence`, and `occurrences_per_year`. The downstream hardening step is the sole source of all annual, weekly, current-state, future-state, reduction, and total figures. `after.hours_per_occurrence` may not exceed `before.hours_per_occurrence`. `occurrences_per_year` must be between 1 and 10,000. `impact_score` and `complexity_score` are integers from 1 to 10. `totals.volume_basis` must say plainly what transcript-supported volume assumptions the audit rests on. Do not hide uncertainty with false precision.

## Workflow content

For every workflow, map the current and proposed future process as a sequence of steps. Each current step has actor `customer` or `company`; each future step has actor `customer`, `company`, or `system`. Use `company` for any human review, approval, or handling that remains. State the trigger, owner role, existing stuck point, what remains human, and tools used. Name a product in `tools_used` only when it appears in the source or is genuinely unavoidable; otherwise use a neutral capability category.

Ordinary implementation detail belongs inside the relevant workflow. Do not elevate customer-record creation, discount-code creation, confirmation messages, record exports/reviews, or immediate follow-ups into separate quantified workflows when they are steps caused by the parent intake event.

## Findings and narrative flow

Describe the relationship between the businesses directly when the source supports it. Preserve the distinction between the entities and their current processes. Build pain points that explain the problem before the solutions: each has severity, source-grounded root cause and impact, confidence, and zero or more references to the workflows that address it. Link each key indicator to its relevant pain point and/or workflow where possible.

`presentation_brief` guides the presenter but does not carry copied figures. `headline_kpis` references only the allowed hours, percentage, or non-cost indicator metrics. If the opening workflow is not the largest time saver, `lead_with` must explain why it still leads. The narrative order is: business context, pain points, then the three proposed workflows and their time savings, followed by the next-phase item when present.

## Future-growth item

`evaluated_need_more_research` is for a viable next-phase opportunity, not a rejection. Its `position` begins exactly: `The following item was considered and assessed in this session. The position below is a considered recommendation, not a dismissal.` Never use the phrase `not recommended`. Provide only source-grounded rationale, sequencing, revisit conditions, and the related captured workflow where applicable. It is rendered as the last document section, with nothing after it.

## Required JSON shape

Return this shape and field names. Omit optional arrays only where noted.

{
  "meta": { "interviewed": ["..."], "departments": ["..."] },
  "engagement_scope": {
    "pitched_by": ["..."], "summary": "...", "in_scope": ["..."], "out_of_scope": ["..."]
  },
  "relationship_context": {
    "description": "...", "shared_systems": ["..."], "handoffs": ["..."], "friction_points": ["..."]
  },
  "executive_summary": {
    "overview": "...", "strengths": "...", "primary_constraint": "..."
  },
  "totals": { "volume_basis": "..." },
  "key_indicators": [{
    "label": "scenario-specific label", "scenario": "...",
    "measures": "handling_time|service_level|volume|rate|ratio|cost|other",
    "value": 0, "value_fmt": "...", "unit": "...", "confidence": "verified|estimate",
    "source_quote": "short source paraphrase", "workflow_ref": "workflow-id or null", "pain_point_ref": "pain-point title or null"
  }],
  "workflows": [{
    "id": "short-slug", "rank": 1, "name": "...", "trigger": "...", "owner_role": "...", "priority_label": "...",
    "confidence": "verified|estimate", "impact_score": 1, "complexity_score": 1,
    "current_steps": [{ "text": "...", "actor": "customer|company" }],
    "future_steps": [{ "text": "...", "actor": "customer|company|system" }],
    "before": { "description": "...", "hours_per_occurrence": 0 },
    "after": { "description": "...", "hours_per_occurrence": 0, "tools_used": ["..."] },
    "occurrences_per_year": 0, "stays_human": "...", "stuck_point": "..."
  }],
  "supporting_flows": [{
    "id": "short-slug", "parent_id": "one of the three workflow IDs", "name": "...",
    "what_it_does": "..."
  }],
  "evaluated_need_more_research": [{
    "id": "short-slug", "name": "...", "raised_by": "...", "what_was_asked": "...", "position": "...",
    "rationale": ["..."], "revisit_conditions": ["..."], "captured_instead": "workflow-id or null"
  }],
  "pain_points": [{
    "title": "...", "severity": "High|Medium|Low", "hours_label": "...", "root_cause": "...",
    "business_impact": "...", "confidence": "verified|estimate", "workflow_refs": ["workflow-id"]
  }],
  "presentation_brief": {
    "lead_with": "...",
    "headline_kpis": [{
      "metric": "hours_freed_per_year|hours_freed_per_week|working_days_freed_per_year|current_hours_per_year|current_hours_per_week|reduction_percent|key_indicator",
      "key_indicator_label": "required only for key_indicator and never a cost indicator"
    }],
    "narrative_arc": "...", "emphasis_notes": ["instructions for the presenter only"]
  }
}

Before returning, check only the essentials: there are exactly three workflows; every supporting flow links to one parent and carries no figures; no cost is calculated; source confidence is honest; time calculations use the stated inputs; and the final JSON is valid.

