'use strict';

// FINAL BUILD
// Combines merged context/logo with the form's own fields into the single
// object Node A consumes. Harden Stats Parsed and Extract Outputted HTML
// both reach back to this node BY NAME -- do not rename it.
//
// Logos travel as an ARRAY. An audit can cover more than one business
// entity and carries a logo for each.

const merged = $input.first().json;
const form = $('Data Upload Dump').first().json;

const SYMBOLS = { AUD: 'A$', USD: '$', GBP: '£', EUR: '€', SEK: 'kr' };
const currency = form['Currency'] || 'AUD';

const rate = Number(form['Labour Rate']);
if (!Number.isFinite(rate) || rate <= 0) {
  throw new Error('Final Build: Labour Rate is missing or not a positive number.');
}

const logoUris = Array.isArray(merged.logo_data_uris) ? merged.logo_data_uris : [];

return [{
  json: {
    context_block: merged.context_block || '',
    // Consultant-side reference only. It is intentionally not interpolated into
    // Node A's user prompt and becomes available only after analysis is hardened.
    next_phase_reference: merged.next_phase_reference || null,
    logo_data_uris: logoUris,
    rate: rate,
    engagement_brief: form['Engagement brief'] || '',
    meta: {
      business_name: form['Company Name'] || null,
