parameters.jsCode:
'use strict';

// BUILD REVIEW PAGE
//
// The dashboard is rendered inside an <iframe srcdoc>, NOT inlined into the
// n8n completion page. Inlining looked fine on screen but was quietly wrong:
//
//   1. document.documentElement inside the completion page is n8n's page, so
//      buildClean() cloned n8n's own chrome into the file the client keeps.
//   2. The tag sweep (which includes DIV and SPAN) made n8n's own interface
//      text contenteditable.
//   3. The dashboard's stylesheet and n8n's stylesheet fought each other.
//   4. window.print() would have printed the n8n page.
//
// Inside the frame, document.documentElement IS the dashboard and nothing
// else, so all four problems disappear and buildClean() needs no special
// cases. The frame is same-origin (srcdoc inherits the parent's origin), so
// the approve POST to the resume URL is a plain same-origin fetch.
//
// The frame is deliberately NOT sandboxed. A sandbox attribute would block
// the blob download unless allow-downloads were set, and there is nothing to
// sandbox against here -- the content is our own generated document.
//
// The editor UI, its stylesheet and the print stylesheet all live INSIDE the
// frame alongside the dashboard, so the whole review experience is one
// self-contained document.
//
// The print stylesheet is deliberately NOT stripped on approve -- it ships
// with the approved document so the client's own copy prints correctly.
// Finalise Edited HTML knows this and matches editor markup by attribute and
// element id, never by raw substring, so the [data-el-edit] selector sitting
// in that stylesheet does not trip it.
//
// PERSISTENT REVIEW LINK
// The response below only ever reaches the browser tab that submitted the
// original form -- there is no separate, reloadable URL for anyone else.
// To give a teammate a link they can open independently, the same review
// page is also written to workflow-level static data (survives across
// executions, unlike anything scoped to this run). A separate small
// webhook chain (Webhook -> Build Review Response -> Respond to Webhook)
// reads it back on demand. That chain is NOT in this node -- this node only
// writes the snapshot. `approved` starts false and is flipped to true by
// Finalise Edited HTML once a real approval lands, so a stale link shows
// "already approved" instead of a dead editor.

const src = $input.first().json;
const html = src.final_html;
const fileName = src.file_name || 'audit-dashboard.html';
const reviewUrl = 'https://YOUR-N8N-HOST/webhook/review-latest';

if (typeof html !== 'string' || !html) {
  throw new Error('Build Review Page: no final_html on the input item.');
}

let resumeUrl = '';
try { resumeUrl = $execution.resumeUrl || ''; } catch (err) { resumeUrl = ''; }
if (!resumeUrl) {
  throw new Error('Build Review Page: $execution.resumeUrl is empty. The Approve button would have nowhere to post to. Run in production mode, and make sure a Wait node exists downstream.');
}

const EDITOR = `
<style id="__el_print__">
@media print {
  #__el_ui__, #__el_done__ { display: none !important; }
  [data-el-edit] { outline: none !important; background: none !important; }
  #site-header { position: static !important; box-shadow: none !important; }
  .header-nav, nav { display: none !important; }

  /* Print the full audit, not the on-screen collapsed dashboard. */
  .workflow-card, .wf-detail, .workflow-detail, .workflow-details,
  .workflow-content, .workflow-expanded, .wf-expanded, .wf-steps,
  .steps-panel, .process-flow, .current-steps, .future-steps,
  [data-workflow-detail], [data-workflow-details] {
    display: block !important;
    height: auto !important;
    min-height: 0 !important;
    max-height: none !important;
    overflow: visible !important;
    visibility: visible !important;
    opacity: 1 !important;
    transform: none !important;
  }
  details { display: block !important; }
  details:not([open]) > :not(summary) { display: block !important; }
  [hidden] { display: block !important; }
  .wf-expand-btn, .wf-steps-toggle, .ind-quote-btn,
  .workflow-expand-btn, .workflow-toggle, [aria-controls][aria-expanded] {
    display: none !important;
  }
  .ind-quote { display: block !important; }

  section { break-inside: auto; padding: 1.2rem 0 !important; }
  .card, .workflow-card, .pain-card, .tier-card, .value-kpi,
  .indicator-chip, .wf-condensed, .opp-item, .enr-card, .build-order-item {
    break-inside: avoid; page-break-inside: avoid;
  }
  h1, h2, h3, h4 { break-after: avoid; page-break-after: avoid; }

  /* Give Chart.js a real, fixed print box and prevent bitmap stretching. */
  .chart-container {
    display: block !important;
    position: relative !important;
    width: 100% !important;
    height: 88mm !important;
    min-height: 88mm !important;
    max-height: 88mm !important;
    overflow: hidden !important;
    break-inside: avoid !important;
    page-break-inside: avoid !important;
  }
  .chart-container canvas, canvas {
    display: block !important;
    box-sizing: border-box !important;
    width: 100% !important;
    height: 100% !important;
    max-width: none !important;
    max-height: none !important;
  }
  a { text-decoration: none !important; }
  body { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
}
@page { margin: 14mm; }
</style>
<style id="__el_style__">
  [data-el-edit]:hover { outline: 1px dashed rgba(91,84,214,.55); outline-offset: 2px; cursor: text; }
  [data-el-edit]:focus { outline: 2px solid #5B54D6; outline-offset: 2px; background: rgba(91,84,214,.06); }
  #__el_ui__, #__el_done__ { position: fixed; right: 20px; bottom: 20px; z-index: 2147483647;
    font: 13px/1.4 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    background: #14171A; color: #fff; padding: 14px 16px; border-radius: 12px;
    box-shadow: 0 10px 30px rgba(0,0,0,.35); max-width: 300px; }
  #__el_done__ { display: none; }
  #__el_ui__ b, #__el_done__ b { display: block; margin-bottom: 4px; font-size: 13px; }
  #__el_ui__ p, #__el_done__ p { margin: 0 0 10px; color: #C9CDD3; font-size: 12px; }
  .__el_btn { width: 100%; padding: 9px 12px; border: 0; border-radius: 8px;
    background: #5B54D6; color: #fff; font-size: 13px; font-weight: 600; cursor: pointer; }
  .__el_btn:disabled { background: #4A4F57; cursor: default; }
  .__el_btn.__el_alt { background: transparent; border: 1px solid #4A4F57; color: #E5E7EB; margin-top: 8px; }
  #__el_status__ { display: block; margin-top: 8px; font-size: 12px; color: #9CA3AF; }
</style>
<div id="__el_ui__">
  <b>Review mode</b>
  <p>Click any text to correct it. Layout and charts are locked.</p>
  <button id="__el_btn__" class="__el_btn" type="button">Approve &amp; Finalise</button>
  <span id="__el_status__"></span>
</div>
<div id="__el_done__">
  <b>Approved</b>
  <p>The HTML file has downloaded. Use the button below for a PDF copy.</p>
  <button id="__el_pdf__" class="__el_btn" type="button">Save as PDF</button>
  <button id="__el_again__" class="__el_btn __el_alt" type="button">Download HTML again</button>
</div>
<script id="__el_script__">
window.addEventListener('load', function () {
  var RESUME_URL = "${resumeUrl}";
  var FILE_NAME = "${fileName}";
  var TAGS = ['H1','H2','H3','H4','H5','H6','P','LI','TD','TH','SPAN','STRONG','EM','B','I','SMALL','FIGCAPTION','BLOCKQUOTE','DT','DD','LABEL','A','DIV'];

  var candidates = document.body.querySelectorAll(TAGS.join(','));
  for (var i = 0; i < candidates.length; i++) {
    var el = candidates[i];
    if (el.closest('#__el_ui__') || el.closest('#__el_done__')) continue;
    if (el.children.length > 0) continue;
    if (!(el.textContent || '').trim()) continue;
    el.setAttribute('contenteditable', 'true');
    el.setAttribute('spellcheck', 'true');
    el.setAttribute('data-el-edit', '1');
  }

  var btn = document.getElementById('__el_btn__');
  var status = document.getElementById('__el_status__');
  var panel = document.getElementById('__el_ui__');
  var donePanel = document.getElementById('__el_done__');
  var approvedHtml = null;

  function buildClean() {
    var clone = document.documentElement.cloneNode(true);
    ['__el_ui__', '__el_done__', '__el_style__', '__el_script__'].forEach(function (id) {
      var n = clone.querySelector('#' + id);
      if (n && n.parentNode) n.parentNode.removeChild(n);
    });
    var marked = clone.querySelectorAll('[data-el-edit]');
    for (var k = 0; k < marked.length; k++) {
      marked[k].removeAttribute('contenteditable');
      marked[k].removeAttribute('spellcheck');
      marked[k].removeAttribute('data-el-edit');
    }
    return '<!DOCTYPE html>' + clone.outerHTML;
  }

  function downloadHtml() {
    if (!approvedHtml) return;
    var blob = new Blob([approvedHtml], { type: 'text/html;charset=utf-8' });
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url;
    a.download = FILE_NAME;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(function () { URL.revokeObjectURL(url); }, 4000);
  }

  btn.addEventListener('click', function () {
    btn.disabled = true;
    status.textContent = 'Saving...';

    approvedHtml = buildClean();

    fetch(RESUME_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ html: approvedHtml })
    }).then(function (r) {
      if (!r.ok) throw new Error('HTTP ' + r.status);

      var live = document.querySelectorAll('[data-el-edit]');
      for (var m = 0; m < live.length; m++) {
        live[m].removeAttribute('contenteditable');
        live[m].removeAttribute('data-el-edit');
      }

      panel.style.display = 'none';
      donePanel.style.display = 'block';
      downloadHtml();
    }).catch(function (e) {
      btn.disabled = false;
      status.textContent = 'Failed: ' + e.message;
    });
  });

  function forEachChart(callback) {
    if (!window.Chart || !window.Chart.instances) return;
    var instances = window.Chart.instances;
    if (typeof instances.forEach === 'function') {
      instances.forEach(callback);
      return;
    }
    Object.keys(instances).forEach(function (key) { callback(instances[key]); });
  }

  function prepareCompletePrint() {
    document.querySelectorAll('details').forEach(function (detail) { detail.open = true; });
    document.querySelectorAll('[aria-expanded="false"]').forEach(function (control) {
      control.setAttribute('aria-expanded', 'true');
    });
    document.querySelectorAll('[hidden]').forEach(function (element) {
      element.removeAttribute('hidden');
    });
    document.querySelectorAll('.wf-detail, .workflow-detail, .workflow-details, .workflow-content, .workflow-expanded, .wf-expanded, .wf-steps, .steps-panel, .process-flow, .current-steps, .future-steps, [data-workflow-detail], [data-workflow-details]').forEach(function (element) {
      element.style.setProperty('display', 'block', 'important');
      element.style.setProperty('height', 'auto', 'important');
      element.style.setProperty('max-height', 'none', 'important');
      element.style.setProperty('overflow', 'visible', 'important');
    });
    forEachChart(function (chart) {
      if (!chart) return;
      try {
        chart.resize();
        chart.update('none');
      } catch (ignore) {}
    });
  }

  window.addEventListener('beforeprint', prepareCompletePrint);
  document.getElementById('__el_pdf__').addEventListener('click', function () {
    prepareCompletePrint();
    window.setTimeout(function () { window.print(); }, 180);
  });
  document.getElementById('__el_again__').addEventListener('click', downloadHtml);
});
</script>
`;

// Inject the editor into the dashboard itself, before the frame is built.
const lower = html.toLowerCase();
const bodyIdx = lower.lastIndexOf('</body>');
const htmlIdx = lower.lastIndexOf('</html>');
const cut = bodyIdx !== -1 ? bodyIdx : htmlIdx;

if (cut === -1) {
  throw new Error('Build Review Page: could not find a closing </body> or </html> tag to inject the editor before.');
}

const framedDoc = html.slice(0, cut) + EDITOR + html.slice(cut);

// srcdoc carries a whole document inside one attribute value. Only & and the
// quote character that delimits the attribute have to be escaped, and & must
// go first or it would double-escape the entities produced by the second
// pass. The browser decodes this back to the exact original before parsing,
// so nothing about the document is altered by the round trip.
const srcdoc = framedDoc
  .split('&').join('&amp;')
  .split('"').join('&quot;');

// The frame covers the whole viewport, which hides the n8n completion page
// underneath it rather than fighting it for layout.
const reviewPage = `<style id="__el_host__">
  html, body { margin: 0 !important; padding: 0 !important; overflow: hidden !important; }
  #__el_frame__ { position: fixed; inset: 0; width: 100vw; height: 100vh;
    border: 0; margin: 0; padding: 0; z-index: 2147483647; background: #F8FAFC; }
</style>
<iframe id="__el_frame__" title="Audit dashboard review" srcdoc="${srcdoc}"></iframe>`;

// Snapshot for the standalone reviewer link. Global static data persists
// across executions (unlike anything read via $() on this run), which is
// exactly what a Webhook -> Code -> Respond to Webhook chain elsewhere in
// this workflow reads back on every visit to that link. `approved` starts
// false here; Finalise Edited HTML flips it to true on a real approval so a
// reloaded or reused link shows "already approved" instead of a dead editor.
const staticData = $getWorkflowStaticData('global');
staticData.latestReview = {
  review_page: reviewPage,
  execution_id: $execution.id,
  approved: false,
  created_at: new Date().toISOString()
};

return [{
  json: {
    review_page: reviewPage,
    review_url: reviewUrl,
    final_html: html,
    file_name: fileName
  }
}];

'use strict';

// FINALISE EDITED HTML
// Takes the document the reviewer approved, re-runs the same integrity checks
// Extract HTML ran on the generated version, and emits the download.
//
// NOTE ON THE EDITOR-MARKUP CHECK:
// The print stylesheet (#__el_print__) deliberately SURVIVES into the approved
// document, and its CSS contains the literal text "data-el-edit" as a selector.
// A plain indexOf('data-el-edit') therefore always matched and killed every
// run. The checks below match the ATTRIBUTE and the ELEMENT ID forms only, so
// leftover CSS selector text is ignored while real editor markup is still
// caught.
//
// TIMEOUT PATH
// The Wait node has a 12-hour "Limit Wait Time" set. If nobody ever POSTs an
// approval, the Wait node auto-continues on its own after that limit, with
// no html on the payload -- this node then throws, same as it always did for
// a missing payload. The only change here is marking the static-data
// snapshot as expired first, so Build Review Response stops presenting a
// live-looking editor whose Approve button would silently fail against an
// execution that has already finished.

const j = $input.first().json;
const body = (j && j.body) ? j.body : j;
const html = body && typeof body.html === 'string' ? body.html.trim() : null;

if (!html) {
  const staticData = $getWorkflowStaticData('global');
  if (staticData.latestReview) {
    staticData.latestReview.expired = true;
  }
  throw new Error('Finalise: no html on the resume payload. Keys received: ' + Object.keys(body || {}).join(', ') + '. If nothing was posted at all, this is most likely the Wait node auto-resuming after its 12-hour limit with no approval received.');
}

if (!/^<!DOCTYPE html>/i.test(html) || !/<\/html>\s*$/i.test(html)) {
  throw new Error('Finalise: the approved document is not a complete HTML page. First 200: ' + html.slice(0, 200));
}

if (html.indexOf('__LOGO_DATA_URI__') !== -1 || html.indexOf('__LOGO_DATA_URI_2__') !== -1) {
  throw new Error('Finalise: a logo placeholder survived into the approved document.');
}

const leftovers = [];
if (/<script[^>]*id=["']__el_script__["']/i.test(html)) leftovers.push('the editor <script> block');
if (/<[^>]+\sid=["'](__el_ui__|__el_done__|__el_style__)["']/i.test(html)) leftovers.push('an editor UI element');
if (/\sdata-el-edit\s*=/i.test(html)) leftovers.push('data-el-edit attributes');
if (/\scontenteditable\s*=\s*["']?true/i.test(html)) leftovers.push('contenteditable attributes');

if (leftovers.length) {
  throw new Error('Finalise: editor markup survived into the approved document (' + leftovers.join(', ') + ') -- buildClean() did not run or did not strip everything.');
}

// Sanity check the reviewer sent back the dashboard, not the n8n page it was
// rendered inside. If the completion page wraps the document, its own chrome
// gets cloned in with it.
if (/n8n-form|__nuxt|id=["']app["']/i.test(html)) {
  console.log('Finalise: the approved HTML contains markup that looks like the n8n form page wrapper. Check what buildClean() is cloning.');
}

const source = $('Build Review Page').first().json;
const fileName = source.file_name || 'audit-dashboard.html';
const before = source.final_html || '';

const staticData = $getWorkflowStaticData('global');
if (staticData.latestReview) {
  staticData.latestReview.approved = true;
}

return [{
  json: {
    edited: html !== before,
    chars_before: before.length,
    chars_after: html.length
  },
  binary: {
    data: {
      data: Buffer.from(html).toString('base64'),
      mimeType: 'text/html',
      fileName: fileName
    }
  }
}];

'use strict';
const staticData = $getWorkflowStaticData('global');
const review = staticData.latestReview;

let html;
if (!review) {
  html = '<!DOCTYPE html><html><body style="font-family:sans-serif;padding:40px;"><p>No review is currently pending.</p></body></html>';
} else if (review.expired) {
  html = '<!DOCTYPE html><html><body style="font-family:sans-serif;padding:40px;"><p>This review (execution ' + review.execution_id + ', created ' + review.created_at + ') expired after 12 hours without approval. Run the audit again to generate a new one.</p></body></html>';
} else if (review.approved) {
  html = '<!DOCTYPE html><html><body style="font-family:sans-serif;padding:40px;"><p>This audit (execution ' + review.execution_id + ') was already approved at ' + review.created_at + '.</p></body></html>';
} else {
  html = review.review_page;
}

return [{ json: { html } }];
